UPDATE directus_operations 
SET options = '{"code":"module.exports = async function(data) {\n  const user = data.$trigger?.payload || {};\n  const id = data.$trigger?.key;\n\n  let finalUsername = user.username;\n  if (!finalUsername) {\n    const emailPrefix = String(user.email || \"\").split(\"@\")[0];\n    const nameBase = String(user.first_name || emailPrefix || \"reader\");\n    const cleanBase = nameBase.toLowerCase().trim().replace(/[^a-z0-9]+/g, \"-\").replace(/^-+|-+$/g, \"\").slice(0, 24) || \"reader\";\n    const suffix = Math.random().toString(36).slice(2, 7);\n    finalUsername = `${cleanBase}-${suffix}`;\n  }\n\n  const displayName = [user.first_name, user.last_name].filter(Boolean).join(\" \").trim() || finalUsername;\n\n  return {\n    user: id,\n    status: \"active\",\n    username: finalUsername,\n    display_name: displayName,\n    is_verified: false\n  };\n};"}'
WHERE name = 'Generate Profile Payload';
